//! The public build-time description of a Zigapagos website: the types a
//! consumer's `build.zig` fills in and hands to `website()` / `serve()` /
//! `e2e()` / `dev()` (see `build/site.zig` and `build/harness.zig`).
//!
//! Everything here is re-exported from the root `build.zig`, so site authors
//! write `zigapagos.Island`, not `zigapagos.api.Island`.

const std = @import("std");

pub const BuildAsset = struct {
    /// Name of this asset
    name: []const u8,
    /// LazyPath of the generated asset.
    ///
    /// The LazyPath cannot be generated by calling `b.path`.
    /// Use the 'assets' directory for non-buildtime assets.
    lp: std.Build.LazyPath,
    /// Installation path relative to the website's asset output path prefix.
    ///
    /// It is recommended to give the file an appropriate file extension.
    /// No need to specify this value if the asset is not meant to be
    /// `link()`ed
    install_path: ?[]const u8 = null,
    /// Installs the asset unconditionally when set to true.
    ///
    /// When set to false, the asset will be installed only if `link()`ed
    /// in a content file or layout (requires `install_path` to be set).
    ///
    /// Note that even when this property is set to false the asset will be
    /// generated by the Zig build system regardless.
    install_always: bool = false,
};

/// A TSX island component made available to a Zigapagos website.
///
/// `root` is the component source file (a `.island.tsx` that default-exports a
/// Preact/`@z/runtime` component). `src` is the exact string used in
/// `<island src="...">` in your templates; the bundled JS module is served at
/// `/islands/<basename-of-src>.js` (so the basename, sans final extension, must
/// be unique across your islands). Islands are SSR'd at build time via the Bun
/// render sidecar and bundled to ESM (Preact kept external → one shared instance).
pub const Island = struct {
    root: std.Build.LazyPath,
    src: []const u8,
};

/// A native SPA (single-page app) made available to a Zigapagos website.
///
/// `root` is the entry component source file (a `.spa.tsx` that exports a
/// `spa` descriptor consumed by the prerender/router). `src` is the exact
/// string used with `--spa`/matched against the SSR pass; the bundled JS
/// module is installed at `spa/<basename-of-src>.js`. `base` is the URL
/// namespace this SPA owns (e.g. `/app`) and must match the module's
/// `export const spa.base` — `build.zig` can't import TS, so `base` is
/// restated here for the configure-time overlap check and install-path
/// namespacing; it is threaded through `--spa=<src>|<base>` and the
/// release-time prerender pass (`src/spa.zig`) asserts the two agree,
/// failing loudly on mismatch (the EXPORTED base remains authoritative for
/// what actually gets prerendered).
pub const Spa = struct {
    root: std.Build.LazyPath,
    src: []const u8,
    base: []const u8,
};

/// A dev-server reverse-proxy rule. Requests whose path matches `prefix` (at a
/// segment boundary) are forwarded to `upstream`; everything else is served
/// static as usual. Dev-only — `serve()` threads these through as
/// `--proxy=<prefix>=<upstream>` and the live server (`src/cli/serve.zig`)
/// streams the response back on the same origin (cookies + SSE included).
///
/// `prefix` is a URL path prefix and must start with `/` (e.g. `/api`).
/// `upstream` is an `http://host[:port]` origin (https upstreams are v1 out of
/// scope). Repeatable: overlapping rules resolve longest-prefix-wins.
pub const Proxy = struct {
    prefix: []const u8,
    upstream: []const u8,
};

pub const Options = struct {
    /// The directory that contains 'zigapagos.ziggy'.
    /// Defaults to the directory where your 'build.zig' lives.
    website_root: ?std.Build.LazyPath = null,

    /// Assets generated by the Zig build system to be made available to Zigapagos.
    build_assets: []const BuildAsset = &.{},

    /// TSX island components (Astro-style islands). When non-empty, Zigapagos is
    /// built from source so islands are SSR'd at build time via the Bun render
    /// sidecar; each island is bundled to an ESM module (`--external @z/runtime`,
    /// one shared Preact instance) and, together with the client hydration
    /// runtime, installed into the output so the pages hydrate in the browser.
    /// Requires `zigapagos == .source` (the default).
    islands: []const Island = &.{},

    /// Native SPAs (single-page apps). When non-empty (even with `islands`
    /// empty), Zigapagos is built from source and the Bun render sidecar is wired
    /// up (SPA-only sites still need it for prerendering); each SPA is
    /// bundled to an ESM module and installed at `spa/<name>.js`. Requires
    /// `zigapagos == .source` (the default).
    spas: []const Spa = &.{},

    /// Dev-server reverse-proxy rules. Only consulted by `serve()` (the live
    /// server); `website()` ignores them (prod routing is the host's job —
    /// nginx/ZigBase). Each rule is emitted as `--proxy=<prefix>=<upstream>`.
    proxies: []const Proxy = &.{},

    /// Which SPA's "/" shell backs the universal `404.html`, named by the
    /// SPA's file basename sans `.spa.tsx` (the same name that keys
    /// `spa/<name>.js` — e.g. "booking" for `app/booking.spa.tsx`). Null (the
    /// default) keeps the historical behavior: the FIRST declared SPA in
    /// `spas`. Naming an SPA that is not declared in `spas` is a
    /// configure-time error, so the choice is explicit and order-independent
    /// rather than silently tracking `spas` declaration order. Only
    /// `website()` consults this (it owns the release-time `404.html`);
    /// `serve()` validates the name but serves its own dev 404 page and
    /// per-namespace fallback shells instead.
    not_found: ?[]const u8 = null,

    /// Emit external (linked) source maps alongside every minified island, SPA
    /// and runtime bundle, and stage them into the release output next to their
    /// scripts (`/islands/<Name>.js.map`, `/spa/<name>.js.map`,
    /// `/zigapagos-runtime.js.map`, …). This is what makes CLIENT-side
    /// symbolication (observability.ts `symbolicate: true`) work in production —
    /// the browser fetches `<script>.map` and rewrites minified frames to their
    /// original source positions.
    ///
    /// Opt-in and OFF by default: maps expose your original (pre-minification)
    /// sources to anyone who can reach the site, and many deployments prefer to
    /// symbolicate SERVER-side from privately-retained maps. Turning this off
    /// keeps release bytes byte-identical to a maps-free build. Enable it (and
    /// `symbolicate: true` in `initObservability`) to symbolicate in the browser.
    source_maps: bool = false,

    /// Path where to output the website, relative to the zig build install
    /// prefix.
    output_path: []const u8 = "",

    /// Tolerate a `$link.page/sibling/sub` or `$site.page(...)` reference to a
    /// page that doesn't exist YET, instead of failing the build. Threaded to
    /// `zigapagos` as `--allow-missing-pages`, uniformly for both `website()`
    /// (release) and `serve()` (the deprecated live server) -- `dev()` needs
    /// no separate wiring, since it re-runs the consumer's own rebuild
    /// command, which goes through `website()`. A tolerated reference renders
    /// as a real, url_prefix-aware `href` (the URL the page will have once
    /// it's written -- a 404 until then) plus a build-log warning. Off by
    /// default: an unintentionally-dangling link should still fail the build.
    /// See `root.Options.allow_missing_pages` for the full design rationale.
    allow_missing_pages: bool = false,

    /// Ignore the presence of other files in the output directory.
    /// When set to `false`, Zigapagos will refuse to output a release to a directory
    /// that contains other files. Note that when set to `true` old files will
    /// **NOT** be deleted by Zigapagos.
    force: bool = false,

    /// Whether Zigapagos should be built from source or grabbed from the
    /// environment. In ephemeral environments like CI runners you might
    /// want to build from source only if you are also saving Zig's cache dirs.
    zigapagos: union(enum) {
        /// Build Zigapagos from source (the default).
        source,
        /// Get Zigapagos from the environment. You can either specify a path
        /// to the executable or leave it null if you have 'zigapagos' available
        /// in PATH.
        path: ?[]const u8,
    } = .source,

    /// Debug settings for Zigapagos.
    debug: struct {
        /// The optimization level to use when building Zigapagos.
        optimize: std.builtin.OptimizeMode = .ReleaseFast,

        /// Logging scopes to enable.
        scopes: []const []const u8 = &.{},
    } = .{},
};

/// `ZIGAPAGOS_BIN` — use an already-built `zigapagos` instead of compiling one.
///
/// A consumer's `zig build` otherwise compiles the generator and its whole
/// dependency tree before rendering a page: 653 compile steps, 632 of them
/// tree-sitter grammar objects across 82 languages, against build work of well
/// under a second for a typical site. In an ephemeral environment that repeats
/// per job — which is exactly the case `Options.zigapagos = .path` was added
/// for, per its own doc comment.
///
/// Reading it from the environment rather than requiring a `build.zig` edit is
/// what makes it usable: CI sets one variable and every consumer in the
/// workspace honours it, including fixtures whose `build.zig` is itself under
/// test and should not be rewritten to suit the harness.
///
/// An explicit `opts.zigapagos = .path` always wins — the env var only
/// overrides the `.source` default, so a project that has deliberately pinned
/// its source build keeps it.
pub fn resolveZigapagos(project: *std.Build, opts: Options) @TypeOf(opts.zigapagos) {
    return switch (opts.zigapagos) {
        .path => opts.zigapagos,
        .source => if (project.graph.environ_map.get("ZIGAPAGOS_BIN")) |bin|
            .{ .path = project.dupe(bin) }
        else
            .source,
    };
}
